package com.shikshasetu.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="ai_assessments",indexes=@Index(name="idx_ai_assessment_student_time",columnList="student_id, assessed_at"))
public class AiAssessment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="student_id",nullable=false) private Long studentId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="student_id",insertable=false,updatable=false,foreignKey=@ForeignKey(name="fk_ai_assessment_student")) private Student student;@Column(name="deterioration_probability",nullable=false) private double deteriorationProbability;@Column(name="support_priority",nullable=false,length=16) private String supportPriority;@Column(name="model_version",nullable=false,length=80) private String modelVersion;@Lob @Column(name="features_json") private String featuresJson;@Lob @Column(name="signals_json") private String signalsJson;@Lob @Column(name="suggestions_json") private String suggestionsJson;@Column(name="assessed_at",nullable=false,updatable=false) private LocalDateTime assessedAt=LocalDateTime.now();protected AiAssessment(){}public AiAssessment(Long s,double p,String b,String v,String f,String g,String h){studentId=s;deteriorationProbability=p;supportPriority=b;modelVersion=v;featuresJson=f;signalsJson=g;suggestionsJson=h;}public Long getId(){return id;}public Long getStudentId(){return studentId;}public double getDeteriorationProbability(){return deteriorationProbability;}public String getSupportPriority(){return supportPriority;}public String getModelVersion(){return modelVersion;}public String getFeaturesJson(){return featuresJson;}public String getSignalsJson(){return signalsJson;}public String getSuggestionsJson(){return suggestionsJson;}public LocalDateTime getAssessedAt(){return assessedAt;}}
